    "\n  fragment ContentTileFragment on ContentType {\n    id\n    title\n    text\n    mimetype\n    contentUrl: url\n    sourceUrl\n    previewUrl\n    mediaUrl\n    ...RichMediaData\n  }\n": typeof types.ContentTileFragmentFragmentDoc,
    "\n  query GetContent($id: ID!) {\n    content(id: $id) {\n      id\n      title\n      text\n      mimetype\n      contentUrl: url\n      sourceUrl\n      # The local copy (external_id -> ci.files), resolved server-side. Preferred\n      # over url/sourceUrl, which for imported photos is often the provider's\n      # web page (e.g. photos.google.com/photo/…) — not an image, and blocked\n      # by the browser when used as one.\n      mediaUrl\n      previewUrl\n      # Poster + click-to-play for a link with rich media (Spotify, YouTube,\n      # Netflix/Prime, …) — see RichMediaCard, the same fragment the memory\n      # drawer's ContentDetails spreads.\n      ...RichMediaData\n      tags {\n        id\n        label\n      }\n    }\n  }\n": typeof types.GetContentDocument,
    "\n  mutation UpdateContentPageFields($input: UpdateContentInput!) {\n    updateContent(input: $input) {\n      id\n      title\n      text\n    }\n  }\n": typeof types.UpdateContentPageFieldsDocument,
    "\n  fragment EventContentTile on ContentType {\n    id\n    title\n    mimetype\n    contentUrl: url\n    sourceUrl\n    previewUrl\n    mediaUrl\n    ...RichMediaData\n  }\n": typeof types.EventContentTileFragmentDoc,
    "\n  query GetEvent($id: ID!) {\n    event(id: $id) {\n      id\n      title\n      description\n\n      # When it happened, what kind it was and where it came from. The page used\n      # to select none of these, so /events/:id could not answer \"when was this?\".\n      startTime\n      endTime\n      eventType\n      sourceSystem\n\n      # A photo/video event's own binary, resolved server-side from its linked\n      # file (null for non-media events), plus the content rows attached to it.\n      mediaContentType\n      mediaUrl\n      previewUrl\n      contents(first: 60) {\n        edges {\n          node {\n            id\n            ...EventContentTile\n          }\n        }\n      }\n\n      tags {\n        id\n        label\n      }\n\n      location {\n        id\n        name\n        properties\n      }\n\n      organizer {\n        id\n        name\n      }\n\n      participants {\n        edges {\n          node {\n            id\n            name\n          }\n        }\n      }\n    }\n  }\n": typeof types.GetEventDocument,
    "\n  mutation UpdateEventPageFields($input: UpdateEventInput!) {\n    updateEvent(input: $input) {\n      id\n      title\n      description\n    }\n  }\n": typeof types.UpdateEventPageFieldsDocument,
