    "\n  query GetPeople($query: String, $first: Int, $after: String) {\n    people(query: $query, first: $first, after: $after) {\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n      edges {\n        cursor\n        node {\n          id\n          name\n          description\n          firstName\n          lastName\n          avatarUrl\n          birthDate\n          isSelf\n          identifiers {\n            kind\n            value\n            rawValue\n            label\n          }\n          interactionStats {\n            eventCount\n            communicationCount\n            lastInteractionAt\n          }\n        }\n      }\n    }\n  }\n": typeof types.GetPeopleDocument,
    "\n  query GetMergedPerson($id: ID!) {\n    person(id: $id) {\n      id\n      name\n      description\n      firstName\n      lastName\n      avatarUrl\n      birthDate\n      isSelf\n      identifiers {\n        kind\n        value\n        rawValue\n        label\n      }\n      interactionStats {\n        eventCount\n        communicationCount\n        lastInteractionAt\n      }\n    }\n  }\n": typeof types.GetMergedPersonDocument,
    "\n  query GetMergeCandidates($first: Int, $after: String) {\n    mergeCandidates(first: $first, after: $after) {\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n      edges {\n        cursor\n        node {\n          id\n          score\n          status\n          detectedBy\n          createdAt\n          evidence {\n            kind\n            value\n            score\n          }\n          people {\n            id\n            name\n            description\n            avatarUrl\n            isSelf\n          }\n        }\n      }\n    }\n  }\n": typeof types.GetMergeCandidatesDocument,
    "\n  mutation MergePeople($input: MergePeopleInput!) {\n    mergePeople(input: $input) {\n      success\n      person {\n        id\n        name\n      }\n    }\n  }\n": typeof types.MergePeopleDocument,
