    "\n  query ScanObjectByIdentifier($namespace: ObjectIdentifierNamespace!, $value: String!) {\n    objectByIdentifier(namespace: $namespace, value: $value) {\n      matched\n      namespace\n      value\n      subjectType\n      confidence\n      item {\n        id\n        name\n        brand\n        model\n      }\n      product {\n        id\n        title\n        brand\n      }\n    }\n  }\n": types.ScanObjectByIdentifierDocument,
    "\n  mutation CreateItem($input: CreateItemInput!) {\n    createItem(input: $input) {\n      item {\n        id\n        name\n        category\n        description\n        brand\n        model\n        currentValue\n        purchasePrice\n        condition\n        lifecycleState\n        quantity\n        acquiredAt\n        acquisitionMethod\n        acquiredFrom\n        manufacturedAt\n        expiresAt\n        lengthMm\n        widthMm\n        heightMm\n        massG\n        volumeMl\n        unitSystem\n        colors\n        colorHex\n        materials\n        composition\n        tags {\n          id\n          label\n        }\n      }\n      success\n    }\n  }\n": types.CreateItemDocument,
