    "\n  query AskDisclosureHistory($input: AskDisclosureHistoryInput) {\n    askDisclosureHistory(input: $input) {\n      truncated\n      rows {\n        id\n        askId\n        askerId\n        peerHandle\n        responderId\n        consentBasis\n        outcome\n        disclosedCount\n        createdAt\n        query {\n          queryType\n          dataClass\n          prompt\n          purpose\n          actor {\n            kind\n            label\n          }\n        }\n      }\n    }\n  }\n": types.AskDisclosureHistoryDocument,
    "\n  query AskDisclosureSummary($input: AskDisclosureSummaryInput) {\n    askDisclosureSummary(input: $input) {\n      truncated\n      summaries {\n        key\n        askerId\n        peerLinkId\n        peerHandle\n        total\n        autoAnswered\n        reviewed\n        declined\n        expired\n        itemsDisclosed\n        asksInWindow\n        itemsInWindow\n        firstAt\n        lastAt\n      }\n    }\n  }\n": types.AskDisclosureSummaryDocument,
