    "\n  mutation CreateAsk($input: CreateAskInput!) {\n    createAsk(input: $input) {\n      success\n      ask {\n        id\n        status\n        createdAt\n        responderId\n        peerHandle\n        query {\n          queryType\n          dataClass\n          prompt\n          purpose\n          actor {\n            kind\n            label\n          }\n        }\n      }\n    }\n  }\n": types.CreateAskDocument,
    "\n  query MyPeerLinks {\n    myPeerLinks {\n      id\n      peerHandle\n      displayName\n      memoryEndpoint\n      personEntityId\n      avatarUrl\n      trustTier\n      status\n      revokedAt\n      createdAt\n    }\n  }\n": types.MyPeerLinksDocument,
