    "\n  mutation ConfirmItemObservation($id: ID!, $itemId: ID) {\n    confirmObservation(id: $id, itemId: $itemId) {\n      id\n      confirmedByUser\n      resolvedObjectId\n      resolutionMethod\n      resolutionConfidence\n    }\n  }\n": types.ConfirmItemObservationDocument,
