    "\n  query GetCommunicationAttachments($id: ID!) {\n    node(id: $id) {\n      __typename\n      id\n      ... on CommunicationType {\n        metadata\n        attachments {\n          fileId\n          contentId\n          filename\n          contentType\n          url\n          previewUrl\n          width\n          height\n          size\n        }\n      }\n    }\n  }\n": types.GetCommunicationAttachmentsDocument,
