    "\n  query GetMergedPerson($id: ID!) {\n    person(id: $id) {\n      id\n      name\n      description\n      firstName\n      lastName\n      avatarUrl\n      birthDate\n      isSelf\n      identifiers {\n        kind\n        value\n        rawValue\n        label\n      }\n      interactionStats {\n        eventCount\n        communicationCount\n        lastInteractionAt\n      }\n    }\n  }\n": types.GetMergedPersonDocument,
