    "\n  mutation MergePlaces($input: MergePlacesInput!) {\n    mergePlaces(input: $input) {\n      success\n      place {\n        id\n        name\n      }\n      counts {\n        events\n        childPlaces\n        relationshipsFrom\n        relationshipsTo\n      }\n    }\n  }\n": types.MergePlacesDocument,
