    "\n  query GetPlaces($query: String, $first: Int, $after: String) {\n    places(query: $query, first: $first, after: $after) {\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n      edges {\n        cursor\n        node {\n          id\n          name\n          description\n          placeKind\n          latitude\n          longitude\n          parent {\n            id\n            name\n            placeKind\n          }\n          visitStats {\n            visitCount\n            firstVisitAt\n            lastVisitAt\n            status\n          }\n        }\n      }\n    }\n  }\n": types.GetPlacesDocument,
